/*
CLEXYT EGGSACT Worker - embedded templates

The blank house workbooks are baked into the app, so a phone has a real,
complete layout the moment it opens - no server call needed for the format.

REBUILT from the live JUDI_DATA_*.xlsx masters. Every captured value was
cleared; the dated day columns, the weekly feed blocks, all 192 pens with
their treatment numbers, the body-weight grid and the egg-quality rows were
all kept. The previous templates had one usable day column (Nketlwane),
none at all (Tsholanang) and no Judi template, which is why a worker without
full-master access could capture data and then find none of it in their
export - there was nowhere for it to land.

Each workbook also carries a "Not yet placed" sheet, so anything that cannot
be written into a cell is listed in the file instead of vanishing.

"Load latest" replaces a template with the real current master, and never the
other way round - see ensureTemplatesInstalled().
*/

